INSERT INTO `ads` VALUES (167,1,68,'جنراتور','جنراتور',100000,1,'0729252510','<p dir=\"rtl\">جنراتور دیزلی ۱۰ کیلووات</p>','	کلوله پشته',4,1,NULL,0,0,'2023-03-27 11:31:36','2023-03-27 11:31:36',NULL,'2023-04-27 11:31:36'),(168,1,40,'خانه فروشی','خانه-فروشی',800000,1,'0799229231','<p dir=\"rtl\">خانه فروشی دارای چار اطاق نشیمن ،دو بسوه</p>','کابل ،عقب موتر فروشی های قصبه.',15,1,NULL,0,0,'2023-03-27 12:18:52','2023-03-27 12:18:52',NULL,'2023-04-27 12:18:52'),(169,1,39,'	روغن 100% خالص سیاه دانه','روغن-100-خالص-سیاه-دانه',70,1,'0744140880','<p dir=\"rtl\"><br>خواص مهم درمانی و خوراکی این گیاه برای همگان هویدا است از سالیان سال مردم عزیزمان به کیفیت درمان وخوراکی اش پی برده از آن استفاده می کنند. اما در بازار نمیتوان با انواع مختلف که است،خالص آنرا دریافت و با خاطر جمع از آن استفاده کرد. این روغن خالص را میتوانید برای تقوست مو، درد های مفاصلی، برای سر درد های شدید، عفونت های سینوزیتی و از بین بردن ویروس ها و مکروبها به عنوان یک انتی بیوتیک طبیعی استفاده کنید.</p>','مزار شریف دروازه بلخ',1,1,NULL,0,0,'2023-03-27 12:20:49','2023-03-27 12:20:49',NULL,'2023-04-27 12:20:49'),(170,1,52,'کمپیوتر HP corei5','کمپیوتر-hp-corei5',9000,1,'0744232308','<p>RAM 6GB HDD 320GB چارج 3 ساعت دارای سیستم پاوربنک. اگر خاموش هم باشد روزولوشن عالی موس تاچ پات کامره شفاف دارای کار کرد عالی و سرعت عالی مال دست خودم است</p>','کابل، سرک دارالامان پلوی کفایت سنتر سرک شورا',6,1,NULL,0,0,'2023-03-27 12:25:20','2023-03-27 12:25:20',NULL,'2023-04-27 12:25:20'),(171,1,45,'	فروش موتر سراچه جرمنی ماشین دبل اتومات','فروش-موتر-سراچه-جرمنی-ماشین-دبل-اتومات',4000,1,'0786091324 ','<p dir=\"rtl\">4000 دالر | 0786091324 | موتر چراچه جرمنی&nbsp;</p>','کابل',10,1,NULL,0,0,'2023-03-27 12:27:26','2023-03-27 12:27:26',NULL,'2023-04-27 12:27:26'),(172,1,51,'مبایل  نوت ۱۰ پلس ۵جی','مبایل-نوت-۱۰-پلس-۵جی',26000,1,'0776431705','<p dir=\"rtl\"><br>نوت ۱۰ + ۵G ۲۵۶ جیبی رم ۱۲ جیبی ۲ سیمکارت هفت رنگ بدون داغ و شیت زدگی وضیعت ۱۰ بر ۱۰ قیمتش ۲۶۰۰۰ با کمی جور امد</p>','	مکرویان سوم',9,1,NULL,0,0,'2023-03-27 12:29:49','2023-03-27