INSERT INTO `blog_categories` VALUES (5,'چگونه فرش دست دوم بخریم','چگونه-فرش-دست-دوم-بخریم','<p dir=\"rtl\">فرش به هر محیطی، زیبایی منحصربه‌فردی می‌بخشد. نقش و نگارهای مختلف و متنوع آن می‌تواند نظر هر فردی را به خود جلب کند. اما همیشه این امکان برای ما وجود ندارد که یک فرش دستباف گران‌قیمت برای خانه خود بخریم. گاهی اوقات نیاز است که برای کاهش هزینه‌ها، فرش دست دوم را به جای یک فرش فرش نو خریداری کنیم.</p><p><figure data-trix-attachment=\"{&quot;contentType&quot;:&quot;image/jpeg&quot;,&quot;filename&quot;:&quot;download.jpg&quot;,&quot;filesize&quot;:14255,&quot;height&quot;:168,&quot;href&quot;:&quot;https://app.imenhost.org/storage/KYWhTxD5mbteSMps17edXC03QaRJvPsesh5ILpQs.jpg&quot;,&quot;url&quot;:&quot;https://app.imenhost.org/storage/KYWhTxD5mbteSMps17edXC03QaRJvPsesh5ILpQs.jpg&quot;,&quot;width&quot;:300}\" data-trix-content-type=\"image/jpeg\" data-trix-attributes=\"{&quot;caption&quot;:&quot;قالین&quot;,&quot;presentation&quot;:&quot;gallery&quot;}\" class=\"attachment attachment--preview attachment--jpg\"><a href=\"https://app.imenhost.org/storage/KYWhTxD5mbteSMps17edXC03QaRJvPsesh5ILpQs.jpg\"><img src=\"https://app.imenhost.org/storage/KYWhTxD5mbteSMps17edXC03QaRJvPsesh5ILpQs.jpg\" width=\"300\" height=\"168\"><figcaption class=\"attachment__caption attachment__caption--edited\">قالین</figcaption></a></figure></p><p dir=\"rtl\">اگر شما نیز به دنبال خرید فرش دست دوم هستید، باید درخریدن آن دقت بیشتر کنید.<br>ما چند روش را به شما عزیزان پشنهاد میکنیم.<br>نحوه تشخیص عمر فرش دست دوم<br>در زمان خرید فرش دست دوم شما کاملا به این امر واقف هستید که فرش چند سالی کار کرده و مورد استفاده قرار گرفته است. توصیه ما این است که اگر هم فرش دست دوم می‌خرید، فرشی را انتخاب کنید که هنوز کیفیت خود را حفظ کرده و سال‌های کمتری مورد استفاده قرار گرفته است.&nbsp;<br>پس برای آنکه تشخیص دهید که هنوز عمر فرش دست دوم باقی مانده است، باید پنجه دست خود را در قسمت‌های مختلف فرش فرو ببرید. اگر دست شما در لابه‌لای پرز فرش فرو رود، فرش قابلیت استفاده را داراست. اگر پرز فرش و یا لایه‌های آن از بین رفته باشد، فرش عمر خود را کرده است و دیگر قابل استفاده نیست .<br>&nbsp;سعی کنید، این کار را در قسمت‌های مختلفی از فرش انجام دهید تا نسبت به خرید خود مطمئن‌تر شوید.&nbsp;<br>بررسی رنگ پریدگی در فرش<br>حال نوبت به بررسی رنگ فرش می‌رسد. رنگ فرش حس زنده بودن را منتقل می‌کند و روح و جان فرش به حساب می‌آید. پس باید حتما قبل از خرید به بررسی میزان رنگ‌ پریدگی فرش دست دوم بپردازید. برای این کار باید فرش را پهن کنید و در مرکز فرش استاد شوید تا دید کامل‌تری نسبت به رنگ فرش داشته باشید. ابتدا دو طرف فرش را به‌ طور کامل با یکدیگر مقایسه کنید و نوع رنگ آن‌ها را با هم مقایسه کنید که اگر اختلاف رنگ به‌نظر برسد، فرش دچار رنگ‌ پریدگی شده است.<br>برای بررسی دقیق‌ تر ترنج فرش را در نظر می‌گیریم و آن را با یک خط فرضی به دو قسمت کاملا مجزا تقسیم می‌کنیم و سپس رنگ گل‌ها و زمینه فرش را با یکدیگر مقایسه می‌کنیم.&nbsp;<br>البته باید فرش را برای بررسی رنگ در مقابل نور طبیعی بررسی کنید تا رنگ‌ها به‌ طورطبیعی نشان داده شوند. همچنین رنگ نقش و نگار و زمینه فرش در جهت خواب فرش، کمی تیره‌تر به‌نظر می‌رسد. پس برای بررسی دقیق‌تر، فرش را در جهت عکس خاب آن بررسی کنید. برای آنکه از خرید فرش خود راضی باشید، حتما رنگ آن را کاملا بررسی کنید و فرشی را انتخاب کنید که دارای رنگ یکنواختی است و رنگ ‌پریدگی در آن دیده نشود.<br>میزان پا خوردن فرش دست دوم<br>•&nbsp; فرش اگر زیاد مورد استفاده قرار بگیرد یا به اصطلاح زیاد پا خورده باشد، نازک می‌شود و در قسمت‌هایی که زیاد در معرض رفت و آمد بوده است، نقاط سفید رنگی دیده می‌شود.&nbsp;<br>•&nbsp; فرش‌های قدیمی‌ تر معمولا دارای بافت درشت‌ تری بوده‌اند که اگر میزان پاخوردگی آن‌ها زیاد باشد، نقطه‌های سفید رنگ بیشتر و بزرگتر به چشم می‌آیند.<br>•&nbsp; فرش‌هایی که این نقاط سفید در آن‌ها زیاد دیده می‌شود، در محیط های پر رفت و آمد استفاده شده‌اند و کیفیت و زیبایی اولیه خود را از دست داده‌اند. پس اگر آن‌ها را خریداری می‌کنید، نباید هزینه زیادی برای آن‌ها بپردازید.<br>•&nbsp; یک نکته مهم دیگر در خصوص پا خوردن فرش این است که فرش را تا بزنید و نحوه قرارگیری لبه‌های کناری آن را با یکدیگر مقایسه کنید. لبه‌های ساده فرش باید صاف باشند و بیرون‌زدگی یا فرورفتگی در آن دید نشود تا زیبایی فرش حفظ شود.<br>قیمت های فرش دست دوم<br>به علت گران بودن فرش&nbsp; دست اول اکثرا مردم ترجیح میدهند دست دوم آنها را تهیه کنند قیمت فرش کهنه بستگی به کارکرد آن دارد اگر چه به مرور زمان قیمت فرش&nbsp; به خاطر قدمت آن&nbsp; یا به قول قدیمی ها پا خوردگی بیشتر بالاتر میرود اما عواملی مانندپارگی ،ساییدگی خاب، تغییر رنگ براثر شستشویا نور،سوختگی یا بید زدگی از قیمت فرش میکاهد عواملی دیگر هم میتوانند روی قیمت فرش تأثیر بگذارند&nbsp; یکی از مواردی که خریدار به آن توجه می کند مواد اولیه آن است مانند جنس فرش&nbsp; که به ۳دسته تقسیم میشوند.</p><p dir=\"rtl\">1-&nbsp; کرکی<br>دسته ای از فرشهای دست دوم ازجنس کرک (موی ریز بدن بعضی حیوانات)است که قیمت این نوع فرشها از فرش ابریشم ارزانتراست واز پشم گرانتر است و به دلیل جنس بسیار خوب وبافت ظریف آن قیمتی نسبتا بالا دارد.<br>2-&nbsp; ابریشمی<br>پیله های کرم های ابریشم منبع تولید نخ های ابریشمی هستند و ویژگی های نخ های ابریشمی چند برابر سایر نخ ها است که در بافت فرش استفاده میشود که از جمله ویژگی های آنها میتوان به این موارد مقاوت بالا ، لطافت ، نازکی و… اشاره کرد.<br>نخ ابریشم به دلیل نازکی تعداد رج های فرش را بالا میبرد و به همین دلیل باید برای بافت آن زمانی بیشتری صرف شود که این خود باعث بالا رفتن قیمت فرش های ابریشمی میشود.</p><p><br>&nbsp;</p>',1,1,'2023-03-15 10:08:27','2023-03-18 14:31:38'),(6,'با تغییر دیکورخانه به استقبال نوروز بروید','با-تغییر-دیکورخانه-به-استقبال-نوروز-بروید',NULL,1,1,'2023-03-16 10:26:47','2023-04-04 11:37:39'),(7,'فروش اجناس سنتی با دیجتالی','فروش-اجناس-سنتی-با-دیجتالی',NULL,1,1,'2023-03-25 09:25:44','2023-04-04 11:36:51');
