ر لوازم الکترونیکی','سایر-لوازم-الکترونیکی',NULL,0,1,'2023-03-27 11:11:30','2023-03-27 11:12:10',NULL),(69,36,'وسایل برقی خانه','وسایل-برقی-خانه',NULL,0,1,'2023-03-27 11:12:43','2023-03-27 11:13:26',NULL),(70,36,'فرش، گلیم و قالیچه','فرش-گلیم-و-قالیچه',NULL,0,1,'2023-03-27 11:13:54','2023-03-27 11:15:25',NULL),(71,36,'الماری و تخت‌خواب','الماری-و-تختخواب',NULL,0,1,'2023-03-27 11:16:03','2023-03-27 11:16:54',NULL),(72,36,'مبل، فرنیچر و لوازم چوبی','مبل-فرنیچر-و-لوازم-چوبی',NULL,0,1,'2023-03-27 11:17:29','2023-03-27 11:17:54',NULL),(73,36,'سایر وسایل خانه','سایر-وسایل-خانه',NULL,0,1,'2023-03-27 11:18:21','2023-03-27 11:19:03',NULL),(74,74,'سایر وسایل شخصی','سایر-وسایل-شخصی',NULL,0,1,'2023-03-27 11:19:34','2023-03-27 11:20:57',NULL),(75,33,'لوازم دوکان و کارخانه','لوازم-دوکان-و-کارخانه',NULL,0,1,'2023-03-27 11:25:11','2023-03-27 11:26:02',NULL),(76,NULL,'استخدام و کاریابی','استخدام-و-کاریابی',NULL,0,1,'2023-03-27 11:26:54','2023-03-27 11:26:54',NULL);
